    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--out',required=True,type=pathlib.Path);ap.add_argument('--legacy',action='store_true');ap.add_argument('--source-pin');ap.add_argument('--main-legacy-control',action='store_true');ap.add_argument('--idle-drain-only',action='store_true');ap.add_argument('--arrival-idle-drain-only',action='store_true');ap.add_argument('--arrival-worker-controls-only',action='store_true');ap.add_argument('--ready-allocation-only',action='store_true');ap.add_argument('--ready-allocation-held',action='store_true');ap.add_argument('--group-admission-only',action='store_true');ap.add_argument('--group-admission-held',action='store_true');ap.add_argument('--group-host-transition-only',action='store_true');ap.add_argument('--group-empty-frame-commutation-only',action='store_true');ap.add_argument('--group-host-negative-only',action='store_true');ap.add_argument('--group-paid-refusal-only',action='store_true');a=ap.parse_args()
    if a.main_legacy_control and not a.legacy:ap.error('--main-legacy-control requires --legacy')
