    out=a.out.resolve();out.relative_to(ROOT/'.local');out.mkdir(parents=True,exist_ok=False)
    default_plan='Baseline main2b92e91c for the limited B+Replay port. Selected B: actual owned COW credit bank, saved FIFO eligibility and atomic Session append/promotion. Component first: entitlement, changing B/prefix/revision, saturation/shrink/purge/duplicate, COW pins, physical cold-next, every allocation refusal and zero terminal ledger. Session affected checks added only for changed contracts. No full/Unity/Player/build/deploy or performance claim.\n'
    probe_plan='Baseline fd0afbce69afdb396b2a8613df50b1bc02dfe132. Actual source route: existing .NET 8 compiler over Unity Runtime+Simulation C# sources and current tools/qa/accrued_credits.cs. Scope: one current-domain real asynchronous PlayableAuthorityTick setup; actual old single-unit request, legitimately earned old-prefix credits, cancellation, actual new single-unit request, eligible new-prefix credits, then frozen authority clock while the real CertifiedRouteWorker runs at CertifiedRouteKernel default cadence. This is an ordinary solver/host-row registration observation, not a group command, group-arrival advance, answer delivery, actor activation, or actor motion. Record PhysicalArrivalEnabled, host FairArrivals, arrival-work count, host-row state, bank conservation and HostSerial, promoted host tick/prefix, and exact new-request host registration or Ready output; classify RED only for a sustained worker wait during the final second of the existing 5000 ms bound on an idle completed old-prefix quantum with the exact eligible new request still in Requests. No pending-map cleanup, external command, SetBudget, signal, Unity, Player, full, build, deploy, or performance claim. Previous pending-map observer attempts remain INVALIDOBSERVATION and are not qualification.\nExplicit --idle-drain-only mode; no Unity or full B matrix.\n'
    host_transition_plan='Baseline 88291e585e777737ed2af3fc4229f25d2fcf31cd. Actual Runtime+Simulation C# plus current QA harness compiled by .NET 8. One real async host interleave: foreign Player Move, 8 legitimate authority ticks, actual worker held at Projection, first trio AttackMove source-read rendezvous, then same worker advanced to and parked at next EndAllocation boundary. Compare pinned host-root identity, token/quantum, navigation/mailbox/actors/foreign intent/geometry/bank and output counters. No extra ticks, manual pump, SetBudget, fake phase, forced output, Unity, Player, Army, full, deploy, or runtime fix. Bounds: prepare 60000ms, next park 10000ms, worker ACK 5000ms. Save initial diff and exact source/binary bindings.\n'
    commutation_plan='Baseline 2938784bcb703e4682279da5b9e4ced487d10c6f. Actual Runtime+Simulation C# plus current QA harness compiled by .NET 8. Reuse the frozen real-thread setup: foreign Player Move, 8 normal authority ticks, actual worker held at Projection, first trio AttackMove source-read rendezvous, then same worker parked at next EndAllocation. Qualify same nonzero token/worker/quantum, every frontier field except Stage, same semantic reads, empty projection queues, same policy/geometry/cursors/provider/scheduler allowance. Expect FIRST AttackMove Applied as exactly one group and three pending requests; foreign intent unchanged; no premature install or motion; held EndAllocation host and bank preserved. No extra ticks, manual pump, SetBudget, fake phase, or forced output. Preparation 60000ms, next park 10000ms, ACK 5000ms. No Unity, Player, Army, full, or deploy.\n'
    control_plan='Baseline 2938784bcb703e4682279da5b9e4ced487d10c6f. Reuse one actual threaded setup: foreign Player Move, 8 normal credits, worker Projection source capture, first trio AttackMove. Host-negative advances the same worker through EndAllocation to PostFlush/token 0 and requires ordinary Host refusal/no effects. Paid-refusal holds the compatible EndAllocation edge, admits the scope, source scratch and first command-map scratch reservations, then refuses the fourth source-derived AllocationAdmission callback; require Overflow/no effects/prior host preservation. No manual ticks/Pump, fake phase, Unity, Player, Army, full or deploy; 60000ms prep, 10000ms boundary wait, 5000ms ACK.\n'
    arrival_plan='Baseline 9dc0a53850114e2825111a78c2ac6c9f7be7449b. Actual Runtime+Simulation C# plus accrued_credits.cs compiled by .NET 8. Ordinary controlled domain, real three-member AttackMove group, old-prefix credits, replacement command, and eligible new-prefix credits. Pin the exact current allocating request objects and their group/member identities before worker start. Freeze authority and observe the real CertifiedRouteWorker at default cadence for exactly 5000ms. RED requires a sustained final-1000ms worker wait on completed idle old-prefix quantum, queued eligible new-prefix credit, exact current group intents still allocating, no covering attempt or physical admission blocker, healthy lane/kernel, and conserved bank. PASS requires actual new-group attempt birth for the same requests after FIFO service. A real TryPromote observation is post-bound only. No synthetic phase/credits, manual pump/wake/SetBudget during observation, Unity, Player, Army, full, build, or deploy.\n'
    (out/'qa-plan.md').write_text(arrival_plan if a.arrival_idle_drain_only else control_plan if a.group_host_negative_only or a.group_paid_refusal_only else commutation_plan if a.group_empty_frame_commutation_only else host_transition_plan if a.group_host_transition_only else 'Baseline 8261ee340f583b3eef7e38a87f55b6d8365673a. Actual Runtime+Simulation C# sources and tools/qa/accrued_credits.cs compiled with .NET 8. Isolated ordinary-domain AttackMove admission at the real CertifiedRouteWorker physical boundary, with held or stable free token. Record exact command status, existing guard observation, authority identities/state, retained bytes/scopes, and refusal atomicity. Preparation uses ordinary Apply and TryAdvance only; no synthetic refusal or readiness requirement. Preparation bound 60000ms, worker stop ACK 5000ms. No Unity/Player/build/deploy/full/Army/performance claim.\n' if a.group_admission_only else 'Baseline QA9dcfe6/runtime main5a02. Actual production C# isolated Ready+foreign allocation probe. Earn600 original-only real B4 credits before normal foreign command request4 and before worker exists; prefix eligibility excludes newer foreign from saved quanta. Freeze authority while real worker drains FIFO. Qualify real Ready proofs then measure one normal Step and fixed30 continuation at '+('held' if a.ready_allocation_held else 'free')+' token. Preserve default27; no Unity/Player/Army/full/deploy. Managed QA console compilation only.\n' if a.ready_allocation_only else probe_plan if a.idle_drain_only else default_plan)
    if any(group_modes) or a.arrival_idle_drain_only or a.arrival_worker_controls_only:
        (out/'initial-diff.patch').write_bytes(subprocess.check_output(['git','diff','HEAD','--','tools/qa/accrued_credits.cs','tools/qa/accrued_credits.py','unity/Assets/Spacewars/Runtime/CertifiedRouteWorker.cs'],cwd=ROOT))
    source=out/'source';source.mkdir();bindings=[]
    paths=subprocess.check_output(['git','ls-tree','-r','--name-only',a.source_pin,'--','unity/Assets/Spacewars/Runtime','unity/Assets/Spacewars/Simulation'] if a.source_pin else ['rg','--files','unity/Assets/Spacewars/Runtime','unity/Assets/Spacewars/Simulation'],cwd=ROOT,text=True).splitlines()
    for name in sorted(p for p in paths if p.endswith('.cs')):
        b=subprocess.check_output(['git','show',a.source_pin+':'+name],cwd=ROOT) if a.source_pin else (ROOT/name).read_bytes();(source/name.replace('/','__')).write_bytes(b);bindings.append(dict(path=name,sha256=sha(b)))
