    cmd=[dotnet,str(dll),str(out)]+(['main-legacy-control'] if a.main_legacy_control else [])+(['arrival-idle-drain-only'] if a.arrival_idle_drain_only else [])+(['arrival-worker-controls-only'] if a.arrival_worker_controls_only else [])+(['idle-drain-only'] if a.idle_drain_only else [])+(['ready-allocation-only'] if a.ready_allocation_only else [])+(['group-admission-only'] if a.group_admission_only else [])+(['group-host-transition-only'] if a.group_host_transition_only else [])+(['group-empty-frame-commutation-only'] if a.group_empty_frame_commutation_only else [])+(['group-host-negative-only'] if a.group_host_negative_only else [])+(['group-paid-refusal-only'] if a.group_paid_refusal_only else [])+(['held'] if a.ready_allocation_held else [])+(['held'] if a.group_admission_held else []);(out/'run-command.json').write_text(json.dumps(cmd))
    with (out/'run.log').open('w') as log:r=subprocess.run(cmd,env=env,stdout=log,stderr=subprocess.STDOUT,timeout=600)
    if not a.source_pin:
        for row in bindings:assert sha((ROOT/row['path']).read_bytes())==row['sha256'],row['path']
    result=json.loads((out/'result.json').read_text()) if (out/'result.json').exists() else {}
    print(json.dumps({'status':result.get('hostTransitionStatus',result.get('arrivalIdleDrain',{}).get('status',result.get('idleDrainBaseline',{}).get('status','PASS' if r.returncode==0 else 'FAIL'))),'result':str(out/'result.json')} if result else {'status':'FAIL','log':str(out/'run.log')}));raise SystemExit(r.returncode)
